(function(root){const headers=['商品分组编号','商品名称','商品介绍','准入类目','图片编号','规格名称','价格','库存','默认规格'];const pictures=['book','pen','cup','bag','shirt','box'];const api={headers,validate(data,existing=[]){const rows=[],groups=new Map();data.forEach((raw,i)=>{if(!raw.some(v=>String(v??'').trim()))return;const v=headers.map((_,n)=>String(raw[n]??'').trim());const r={line:i+2,values:v,errors:[],warning:'',status:'待导入'};rows.push(r);if(!v[0])r.errors.push('缺少商品分组编号');if(!v[1])r.errors.push('缺少商品名称');if(!v[2])r.errors.push('缺少商品介绍');if(v[3]!=='普通白名单商品')r.errors.push('仅允许普通白名单商品，专项许可及其他类目不能批量导入');if(v[4]&&!pictures.includes(v[4]))r.errors.push('图片编号不存在');if(!v[5])r.errors.push('缺少规格名称');if(!/^\d+(\.\d{1,2})?$/.test(v[6])||Number(v[6])<=0||!Number.isSafeInteger(Math.round(Number(v[6])*100)))r.errors.push('价格须大于 0，最多两位小数');if(!/^\d+$/.test(v[7])||!Number.isSafeInteger(Number(v[7])))r.errors.push('库存须为非负整数');if(!['是','否'].includes(v[8]))r.errors.push('默认规格只能填写是或否');if(existing.some(p=>p.name.trim()===v[1]))r.warning='店内已有同名商品，请检查';const key=v[0]||'缺失编号行'+r.line;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);});const valid=[];for(const [key,list] of groups){const first=list[0].values;for(const r of list)for(const col of [1,2,3,4])if(r.values[col]!==first[col])r.errors.push('同组'+headers[col]+'不一致');if(list.filter(r=>r.values[8]==='是').length!==1)list.forEach(r=>r.errors.push('同组必须恰好有一个默认规格'));const bad=list.some(r=>r.errors.length);for(const r of list){r.status=r.errors.length?'错误':bad?'同组受影响':'待导入';if(bad&&!r.errors.length)r.errors.push('同组其他行有错误，整组暂不导入');}if(!bad)valid.push({group:key,name:first[1],description:first[2],category:'ordinary',image:first[4],status:'草稿',variants:list.map(r=>({name:r.values[5],price:r.values[6],stock:r.values[7]})),defaultVariant:list.findIndex(r=>r.values[8]==='是')});}return {rows,valid,totalGroups:groups.size};}};if(typeof module!=='undefined')module.exports=api;else root.ImportModel=api;})(globalThis);
